[HtmlTargetElement("email")]
public class EmailTagHelper : TagHelper
{
    public string Address { get; set; }
    public override void Process(TagHelperContext c, TagHelperOutput o)
    {
        o.TagName = "a";
        o.Attributes.SetAttribute("href", $"mailto:{Address}");
    }
}

